				if (entry.sendPolicy === "deny") {
					lines.push(
						"",
						"⚠️ SEND POLICY: DENY - Do not send messages externally.",
					);
				}
				if (entry.totalTokens) {
					lines.push(`Total Tokens Used: ${entry.totalTokens}`);
				}
			}

			return {
				text: lines.join("\n"),
				values: {
					sessionId: context.sessionId,
