		getStreamedText: () => {
			const buffered = extractor.flush?.() ?? "";
			if (buffered) {
				streamedText += buffered;
			}
			return streamedText;
		},
		isComplete: () => extractor.done,
		reset: () => {
			extractor.reset?.();
			streamedText = "";
		},
		/** Append text to the streamed content buffer */
		appendText: (text: string) => {
			streamedText += text;
		},
	}

